package com.ruoyi.system.service.impl;
import java.util.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.ruoyi.common.core.domain.model.MpLoginUser; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.YcMeetingFeedback; import com.ruoyi.system.mapper.YcMeetingFeedbackMapper; import com.ruoyi.system.service.IYcMeetingFeedbackService;
@Service public class YcMeetingFeedbackServiceImpl implements IYcMeetingFeedbackService { @Autowired private YcMeetingFeedbackMapper mapper; @Override public int submit(Long activityId,Integer rating,String content,MpLoginUser user){if(activityId==null)throw new ServiceException("activityId required");if(rating!=null&&(rating<1||rating>5))throw new ServiceException("rating must be between 1 and 5");if(content!=null&&content.length()>1000)throw new ServiceException("feedback too long");YcMeetingFeedback f=new YcMeetingFeedback();f.setActivityId(activityId);f.setMpUserId(user==null?null:user.getUserId());f.setRating(rating);f.setContent(content==null?"":content.trim());return mapper.insert(f);} @Override public List<YcMeetingFeedback> list(Long activityId){return mapper.selectList(activityId);} @Override public Map<String,Object> stats(Long activityId){Map<String,Object> s=mapper.selectStats(activityId);return s==null?Collections.emptyMap():s;} }
